import Alpaca from '@alpacahq/alpaca-trade-api';
import type { OhlcvData } from '../../market-scout/pattern-detectors/pattern-detector.interface';
import { calculateTechnicalIndicators, analyzeMarketStructure } from '../../signal-validator/technical-indicators';
import type { TechnicalIndicators, MarketStructure } from '../../signal-validator/types';
import type { Logger } from '../brokers/types';
import { type WatchlistConfig, DEFAULT_WATCHLIST_CONFIG } from './watchlist';

/**
 * A stock signal generated by the signal generator.
 */
export interface StockSignal {
    symbol: string;
    action: 'BUY' | 'SELL' | 'WAIT';
    confidence: number;
    reasoning: string[];
    indicators: {
        rsi: number;
        macd: number;
        macdSignal: number;
        trend: string;
        trendStrength: number;
        bollingerPosition: string; // 'above_upper' | 'near_upper' | 'middle' | 'near_lower' | 'below_lower'
        volumeState: string;
    };
    currentPrice: number;
    timestamp: Date;
}

/**
 * StockSignalGenerator
 *
 * Fetches OHLCV data from Alpaca and runs the existing technical analysis
 * library to generate BUY/SELL/WAIT signals for a watchlist of stocks.
 */
export class StockSignalGenerator {
    private alpaca: any;
    private logger: Logger;
    private config: WatchlistConfig;

    constructor(alpaca: any, logger: Logger, config?: Partial<WatchlistConfig>) {
        this.alpaca = alpaca;
        this.logger = logger;
        this.config = { ...DEFAULT_WATCHLIST_CONFIG, ...config };
    }

    /**
     * Scan all symbols in the watchlist and generate signals.
     */
    async scan(): Promise<StockSignal[]> {
        const signals: StockSignal[] = [];

        this.logger.info(`📡 Scanning ${this.config.symbols.length} symbols...`);

        for (const symbol of this.config.symbols) {
            try {
                const signal = await this.analyzeSymbol(symbol);
                if (signal && signal.action !== 'WAIT') {
                    signals.push(signal);
                    this.logger.info(`🎯 Signal: ${signal.action} ${symbol} (Confidence: ${(signal.confidence * 100).toFixed(0)}%) — ${signal.reasoning[0]}`);
                }
            } catch (error: any) {
                this.logger.warn(`Failed to analyze ${symbol}: ${error.message}`);
            }
        }

        this.logger.info(`✅ Scan complete. Found ${signals.length} actionable signal(s).`);
        return signals;
    }

    /**
     * Analyze a single symbol and generate a signal.
     */
    private async analyzeSymbol(symbol: string): Promise<StockSignal | null> {
        // 1. Fetch OHLCV data from Alpaca
        const candles = await this.fetchBars(symbol);
        if (candles.length < 50) {
            this.logger.debug(`Insufficient data for ${symbol}: only ${candles.length} bars.`);
            return null;
        }

        // 2. Calculate technical indicators using the existing library
        const indicators: TechnicalIndicators = calculateTechnicalIndicators(candles);
        const structure: MarketStructure = analyzeMarketStructure(candles, indicators);

        // 3. Run multi-factor signal logic
        return this.generateSignal(symbol, indicators, structure);
    }

    /**
     * Fetch historical bars from Alpaca and convert to OhlcvData format.
     */
    private async fetchBars(symbol: string): Promise<OhlcvData[]> {
        const bars: OhlcvData[] = [];

        // Calculate start date based on barsCount
        const endDate = new Date();
        const startDate = new Date();
        if (this.config.timeframe === '1Day') {
            startDate.setDate(startDate.getDate() - Math.ceil(this.config.barsCount * 1.5)); // Extra buffer for weekends
        } else if (this.config.timeframe === '1Hour') {
            startDate.setHours(startDate.getHours() - this.config.barsCount * 2);
        } else {
            startDate.setMinutes(startDate.getMinutes() - this.config.barsCount * 30);
        }

        const barsIterator = this.alpaca.getBarsV2(symbol, {
            start: startDate.toISOString(),
            end: endDate.toISOString(),
            timeframe: this.config.timeframe,
            limit: this.config.barsCount,
            feed: 'iex', // IEX feed is free for all paper accounts; SIP requires paid subscription
        });

        for await (const bar of barsIterator) {
            bars.push({
                timestamp: new Date(bar.Timestamp).getTime(),
                open: bar.OpenPrice,
                high: bar.HighPrice,
                low: bar.LowPrice,
                close: bar.ClosePrice,
                volume: bar.Volume,
            });
        }

        return bars;
    }

    /**
     * Multi-factor signal generation logic.
     * Combines RSI, MACD, Bollinger Bands, Trend, and Volume to produce a weighted signal.
     */
    private generateSignal(
        symbol: string,
        indicators: TechnicalIndicators,
        structure: MarketStructure,
    ): StockSignal {
        let buyScore = 0;
        let sellScore = 0;
        const reasoning: string[] = [];

        // --- Factor 1: RSI (weight: 25%) ---
        // Trend-aware zones: shift thresholds based on trend direction + strength
        // In uptrend: raise overbought zone (momentum is strength, not weakness)
        // In downtrend: lower oversold zone (falling knife, not value)
        const trendShift = Math.round(structure.trendStrength * 10); // 0-10 RSI points
        const oversold = structure.trend === 'downtrend' ? 30 - trendShift : 30;
        const approachingOversold = structure.trend === 'downtrend' ? 40 - trendShift : 40;
        const overbought = structure.trend === 'uptrend' ? 70 + trendShift : 70;
        const approachingOverbought = structure.trend === 'uptrend' ? 60 + trendShift : 60;

        if (indicators.rsi14 < oversold) {
            buyScore += 0.25;
            reasoning.push(`RSI oversold (${indicators.rsi14.toFixed(1)}, threshold ${oversold})`);
        } else if (indicators.rsi14 < approachingOversold) {
            buyScore += 0.10;
            reasoning.push(`RSI approaching oversold (${indicators.rsi14.toFixed(1)})`);
        } else if (indicators.rsi14 > overbought) {
            sellScore += 0.25;
            reasoning.push(`RSI overbought (${indicators.rsi14.toFixed(1)}, threshold ${overbought})`);
        } else if (indicators.rsi14 > approachingOverbought) {
            sellScore += 0.10;
            reasoning.push(`RSI approaching overbought (${indicators.rsi14.toFixed(1)})`);
        }

        // --- Factor 2: MACD Cross (weight: 25%) ---
        if (indicators.macdHistogram > 0 && indicators.macd > indicators.macdSignal) {
            buyScore += 0.25;
            reasoning.push('MACD bullish crossover');
        } else if (indicators.macdHistogram < 0 && indicators.macd < indicators.macdSignal) {
            sellScore += 0.25;
            reasoning.push('MACD bearish crossover');
        }

        // --- Factor 3: Bollinger Bands (weight: 20%) ---
        const bbPosition = this.getBollingerPosition(indicators);
        if (bbPosition === 'below_lower') {
            buyScore += 0.20;
            reasoning.push('Price below lower Bollinger Band');
        } else if (bbPosition === 'near_lower') {
            buyScore += 0.10;
            reasoning.push('Price near lower Bollinger Band');
        } else if (bbPosition === 'above_upper') {
            sellScore += 0.20;
            reasoning.push('Price above upper Bollinger Band');
        } else if (bbPosition === 'near_upper') {
            sellScore += 0.10;
            reasoning.push('Price near upper Bollinger Band');
        }

        // --- Factor 4: Trend Filter (weight: 20%) ---
        if (structure.trend === 'uptrend') {
            buyScore += 0.15 * structure.trendStrength;
            if (structure.trendStrength > 0.6) {
                reasoning.push(`Strong uptrend (${(structure.trendStrength * 100).toFixed(0)}%)`);
            }
            // Penalize sell signals in uptrend
            sellScore *= 0.5;
        } else if (structure.trend === 'downtrend') {
            sellScore += 0.15 * structure.trendStrength;
            if (structure.trendStrength > 0.6) {
                reasoning.push(`Strong downtrend (${(structure.trendStrength * 100).toFixed(0)}%)`);
            }
            // Penalize buy signals in downtrend
            buyScore *= 0.5;
        }

        // --- Factor 5: Volume Confirmation (weight: 10%) ---
        if (structure.volumeState === 'high') {
            // High volume confirms the signal direction
            if (buyScore > sellScore) {
                buyScore += 0.10;
                reasoning.push('High volume confirms bullish move');
            } else if (sellScore > buyScore) {
                sellScore += 0.10;
                reasoning.push('High volume confirms bearish move');
            }
        }

        // --- Determine final action ---
        let action: 'BUY' | 'SELL' | 'WAIT';
        let confidence: number;

        // Net-score filter: require clear directional conviction
        // Prevents ambiguous signals where both BUY and SELL score similarly
        const netScore = Math.abs(buyScore - sellScore);
        const minNetScore = 0.15;

        if (netScore < minNetScore) {
            // Too uncertain — conflicting signals cancel out
            action = 'WAIT';
            confidence = 0;
        } else if (buyScore > sellScore && buyScore >= 0.10) {
            // Low floor (0.10 instead of 0.35): let macro boost in evaluateSignal()
            // push borderline signals over min_confidence threshold (0.40)
            action = 'BUY';
            confidence = Math.min(buyScore, 0.95);
        } else if (sellScore > buyScore && sellScore >= 0.10) {
            action = 'SELL';
            confidence = Math.min(sellScore, 0.95);
        } else {
            action = 'WAIT';
            confidence = 0;
        }

        if (reasoning.length === 0) {
            reasoning.push('No strong signals detected');
        }

        return {
            symbol,
            action,
            confidence,
            reasoning,
            indicators: {
                rsi: indicators.rsi14,
                macd: indicators.macd,
                macdSignal: indicators.macdSignal,
                trend: structure.trend,
                trendStrength: structure.trendStrength,
                bollingerPosition: bbPosition,
                volumeState: structure.volumeState,
            },
            currentPrice: indicators.currentPrice,
            timestamp: new Date(),
        };
    }

    /**
     * Determine where the current price sits relative to Bollinger Bands.
     */
    private getBollingerPosition(indicators: TechnicalIndicators): string {
        const { currentPrice, bollingerUpper, bollingerLower, bollingerMiddle } = indicators;
        const bandWidth = bollingerUpper - bollingerLower;
        const upperThreshold = bollingerUpper - bandWidth * 0.1;
        const lowerThreshold = bollingerLower + bandWidth * 0.1;

        if (currentPrice > bollingerUpper) return 'above_upper';
        if (currentPrice > upperThreshold) return 'near_upper';
        if (currentPrice < bollingerLower) return 'below_lower';
        if (currentPrice < lowerThreshold) return 'near_lower';
        return 'middle';
    }
}
